package vn.iotstar.service.impl; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.iotstar.dto.RegisterDTO; import vn.iotstar.entity.*; import vn.iotstar.repository.*; import vn.iotstar.service.*; @Service @RequiredArgsConstructor public class AuthServiceImpl implements AuthService{private final UserRepository users;private final RoleRepository roles;private final PasswordEncoder encoder;private final OtpService otp; @Transactional public void register(RegisterDTO d){if(!d.getPassword().equals(d.getConfirmPassword()))throw new IllegalArgumentException("Mật khẩu xác nhận không đúng");if(users.existsByUsername(d.getUsername()))throw new IllegalArgumentException("Username đã tồn tại");if(users.existsByEmail(d.getEmail()))throw new IllegalArgumentException("Email đã tồn tại");Role r=roles.findByName("ROLE_USER").orElseThrow(()->new IllegalStateException("Chưa có ROLE_USER"));users.save(User.builder().username(d.getUsername()).email(d.getEmail()).password(encoder.encode(d.getPassword())).fullName(d.getFullName()).enabled(false).role(r).build());otp.sendRegisterOtp(d.getEmail());} @Transactional public boolean verifyRegister(String e,String o){if(!otp.verifyRegisterOtp(e,o))return false;User u=users.findByEmail(e).orElseThrow();u.setEnabled(true);return true;}public void forgotPassword(String e){if(!users.existsByEmail(e))throw new IllegalArgumentException("Email không tồn tại");otp.sendResetPasswordOtp(e);}public boolean verifyResetOtp(String e,String o){return otp.verifyResetPasswordOtp(e,o);}@Transactional public void resetPassword(String e,String p){User u=users.findByEmail(e).orElseThrow();u.setPassword(encoder.encode(p));}}